uint64_t fileChecksum(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("Cannot checksum file: "+path.string());uint64_t hash=14695981039346656037ull;char buffer[8192];while(in){in.read(buffer,sizeof(buffer));for(std::streamsize i=0;i<in.gcount();++i){hash^=static_cast<unsigned char>(buffer[i]);hash*=1099511628211ull;}}if(!in.eof())throw std::runtime_error("Failed reading checksum file");return hash;}
void atomicReplaceFile(const std::filesystem::path& from,const std::filesystem::path& to){
#ifdef _WIN32
 if(!MoveFileExW(from.c_str(),to.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Atomic session pointer replacement failed");
#else
 std::filesystem::rename(from,to);
#endif
}
